'use strict';
const $=id=>document.getElementById(id),stage=document.querySelector('.stage'),drafts=new Map(),history=new Map(),settings=new Map();
let items=[],family='instrument',editing=false,drag=null,generation=0;
const key=()=>family+'-'+$('size').value.replace('*','x'),tick=new Date('2026-11-02T09:10:00+08:00').getTime();
const alternate={instrument:{'#121517':'#14202A','#1C2225':'#1B2B38','#282F32':'#243B4C','#E5F866':'#FFAB66'},paper:{'#B66341':'#6C7960','#F1DEC1':'#E4DCC8','#E5C07F':'#D4C48D'},pop:{'#3348B8':'#70427B','#F88D5A':'#F6AFD0','#DDD6F4':'#B5DDD8','#242D76':'#42264A'}};
function remember(){const k=key();history.set(k,[...(history.get(k)||[]),{pack:structuredClone(drafts.get(k)),settings:{...settings.get(k)}}].slice(-20));$('undo').disabled=false;}
function render(){const k=key(),pack=drafts.get(k);if(!pack)return;const fixture=FridgePreviewData.profile(pack,tick,$('data').value),projection=FridgePreviewData.project(pack,fixture);const output=FridgeWeb.renderPackage(projection.pack,420,tick);if(output.issues.length)throw Error(output.issues.join(', '));stage.innerHTML=output.svg;stage.classList.toggle('editing',editing);$('mode').textContent=editing?'结束自由编辑':'自由编辑';$('undo').disabled=!(history.get(k)||[]).length;document.querySelectorAll('.family').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.family===family)));$('status').textContent=editing?'拖动画布中的卡片':'';}
async function select(){const mine=++generation,k=key();if(!drafts.has(k)){const item=items.find(m=>m.id===k),pack=await(await fetch(item.canvas)).json();pack.assetDimensions={};await Promise.all(pack.assets.map(a=>new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>{pack.assetDimensions[a.key]={width:img.naturalWidth,height:img.naturalHeight};resolve();};img.onerror=reject;img.src='data:image/png;base64,'+a.data;})));drafts.set(k,pack);settings.set(k,{palette:'original',content:'clock'});}if(mine!==generation)return;$('palette').value=settings.get(k).palette;$('content').value=settings.get(k).content;render();}
$('size').onchange=()=>{select().catch(fail);};$('data').onchange=render;
$('palette').onchange=()=>{remember();const k=key(),pack=drafts.get(k),toAlternate=$('palette').value==='alternate',map=alternate[family],convert=c=>toAlternate?(map[c]||c):(Object.keys(map).find(x=>map[x]===c)||c);pack.state.background.color=convert(pack.state.background.color);for(const c of pack.state.cards){c.paper=convert(c.paper);c.ink=convert(c.ink);}settings.get(k).palette=$('palette').value;render();};
$('content').onchange=()=>{remember();const k=key(),c=drafts.get(k).state.cards.find(c=>c.id==='time');c.capability={k:$('content').value,...($('content').value==='worldclock'?{zone:'Asia/Tokyo',city:'东京'}:{}),readingStyle:'plain',readingBlend:'bare',readingOpacity:0};settings.get(k).content=$('content').value;render();};
$('mode').onclick=()=>{editing=!editing;render();};
$('undo').onclick=()=>{const k=key(),prev=(history.get(k)||[]).pop();if(!prev)return;drafts.set(k,prev.pack);settings.set(k,prev.settings);$('palette').value=prev.settings.palette;$('content').value=prev.settings.content;render();};
stage.onpointerdown=e=>{if(!editing)return;const node=e.target.closest('[data-fridge-card]');if(!node)return;const id=node.getAttribute('data-fridge-card'),pack=drafts.get(key()),card=pack.state.cards.find(c=>c.id===id);remember();drag={key:key(),id,x:e.clientX,y:e.clientY,cardX:card.x,cardY:card.y,width:stage.getBoundingClientRect().width};stage.setPointerCapture(e.pointerId);};
stage.onpointermove=e=>{if(!drag||drag.key!==key())return;const card=drafts.get(key()).state.cards.find(c=>c.id===drag.id);card.x=Math.max(0,Math.min(344-card.w,drag.cardX+(e.clientX-drag.x)/drag.width*344));card.y=Math.max(0,Math.min((344-card.h)/344*470,drag.cardY+(e.clientY-drag.y)/drag.width*470));render();};
stage.onpointerup=stage.onpointercancel=()=>{drag=null;};
$('download').onclick=()=>{const pack=structuredClone(drafts.get(key()));delete pack.assetDimensions;const url=URL.createObjectURL(new Blob([JSON.stringify(pack,null,2)+'\n'],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=key()+'.fridge';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
function fail(e){$('status').textContent='无法打开：'+e.message;}
fetch('modules.json').then(r=>r.json()).then(data=>{items=data;for(const m of items.filter(m=>m.dimension==='4*4')){const b=document.createElement('button');b.className='family';b.dataset.family=m.family;b.setAttribute('aria-pressed','false');const img=document.createElement('img');img.src='previews/'+m.id+'-demo-300.png';img.alt=m.name;const label=document.createElement('span');label.textContent=m.name;b.append(img,label);b.onclick=()=>{family=m.family;select().catch(fail);};document.querySelector('.families').append(b);}return select();}).catch(fail);
